// TH15 v1.00b Stage 3 MBoss1; source st03mbs.ecl.txt:48-83.
// Source timerReset is 0; common MBoss entry keeps spawn(-192,-64),
// 100-frame move to (0,128), then MBoss1 after 40 frames.
// Card frame 0 = segment start; source 0 sits at OPENING_BUFFER.

const TIME_LIMIT: int = 1444;
const OPENING_BUFFER: int = 120;

// TH15 type aliases reuse the already-verified 352+type*16 catalog rows.
const TH15_PELLET2: int = 368;   // src etSprite type 1, color 4
const TH15_BIG_BALL2: int = 656; // src etSprite type 19, color 1

// --- source MBoss1_at (st03mbs.ecl.txt:85-175), one call = 100 x 2 frames ---
// A/B/f0 are BAM ints: A = masked base angle, B = +/-1deg step, f0 = polar
// spawn offset. Emitter0 fires on even subframes, emitter1 on odd subframes.
sub mboss1_at(a0: int, b: int, f0_start: int) {
    var rank: int = global(GVAR_RANK);
    var n0: int = 2;
    var n1: int = 2;
    var s_start: fx = 1fx;
    var s_end: fx = 3fx;
    var f1: fx = 0.5fx;
    if rank == 2 {                       // Hard: 3 ways, speed 2->4, *0.7
        n0 = 3;
        n1 = 3;
        s_start = 2fx;
        s_end = 4fx;
        f1 = 0.7fx;
    }
    if rank == 3 {                       // Lunatic: 4/3 ways, speed 2->4, *0.4
        n0 = 4;
        n1 = 3;
        s_start = 2fx;
        s_end = 4fx;
        f1 = 0.4fx;
    }

    // src etNew/etSprite/etAim(3)/etCount/etAngle; etCopy(1,0)+etSprite(1,1,4).
    sh_reset(0);
    sh_sprite(0, TH15_BIG_BALL2, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n0, 1);
    sh_reset(1);
    sh_sprite(1, TH15_PELLET2, 4);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, n1, 1);

    var f0: int = f0_start;
    for i in 0..100 {
        // floatTime(1,%C,200,0,start,goal): linear, reads 2i/200 per iteration.
        var c: fx = s_start + (s_end - s_start) * (i as fx / 100fx);
        sh_speed(0, c, 0fx);
        sh_offset_rad(0, f0 as angle, 64fx);
        sh_angle(0, (a0 + 2 * i * b) as angle, 0deg);
        sh_dist(0, 0fx - 4fx * c);       // EX ANIM a=1: position -= 4*velocity
        sh_fire(0);
        wait(1);
        if rank >= 1 {
            var c1: fx = c * f1;
            var r: int = rand(65536) - 32768; // %RANDRAD, one sample per wave
            sh_speed(1, c1, 0fx);
            sh_offset_rad(1, r as angle, 64fx);
            sh_angle(1, (a0 + (2 * i + 1) * b) as angle, 0deg);
            sh_dist(1, 0fx - 4fx * c1);
            sh_fire(1);
        }
        f0 = f0 + 40503;                 // src %F0 += 3.883222 rad per iteration
        wait(1);
    }
}

// --- source MBoss1 loop (st03mbs.ecl.txt:80-81), wait(160) done by caller ---
sub mboss1_body() {
    var rank: int = global(GVAR_RANK);
    var toggle: int = 0;
    loop {
        if toggle == 0 {
            if rank == 2 { mboss1_at(16384, -182, 49152); }
            else { mboss1_at(32768, -182, 0); }
        } else {
            if rank == 2 { mboss1_at(16384, 182, 49152); }
            else { mboss1_at(0, 182, 32768); }
        }
        toggle = 1 - toggle;
        wait(20);
        card_move_rand();                // src moveRand(60,4,1.0), non-blocking
        card_wait(60);                   // src trailing wait(60)
    }
}

// --- moveRand helper adapted from TH16 movement.md to moveLimit(0,128,280,256) ---
// Actual clamp x[-140,140] y[0,256]; direction inner zone x+/-70, y64..192.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// --- common MBoss entry + MBoss1 ---
async sub real_boss() {
    set_invuln(65535);
    set_hitbox(40fx);
    set_hurtbox(48fx);
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT); // src movePosTime(100,4,0,128)
    wait(40);                                // src common MBoss wait(40)
    wait(160);                               // src MBoss1 wait(160)
    mboss1_body();
}

// --- training shell: independent control, real boss carries the source attack ---
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-192fx, -64fx, 13600, 0, 0, 0, real_boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
